    var next2 := helpers.SafeTemperatureConstrainedStep(lm, parser, constrainedPrompt2, currentConstrainedOut, 0.8, eosToken);
    if next2 == eosToken {
      break;
    } else {
      var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
      generated := ag2;
      insideConstrainedOut := ai2;
      currentConstrainedOut := ac2;
    }
