}

// Phase 4: Force a final answer span if no span was produced and budget remains
if !insideConstrainedOut && steps < maxSteps {
  // Check if we've already produced a valid span
  var openCount := CSDHelpers.CountTokenOccurrences(generated, "<<");
  var closeCount := CSDHelpers.CountTokenOccurrences(generated, ">>");
  if openCount == 0 || openCount > closeCount {
    // No complete span yet - force open one and use CloseSpanWithinBudget
    if steps + 2 <= maxSteps {
      var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
      generated := fg;
      insideConstrainedOut := fi;
      currentConstrainedOut := fc;
      steps := steps + 1;

      // Now use CloseSpanWithinBudget with remaining budget
      var remainBudget := maxSteps - steps;
      if remainBudget > 0 {
        var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainBudget);
        generated := wg;
        insideConstrainedOut := wi;
        currentConstrainedOut := wc;
        steps := maxSteps;
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Core insight from failure analysis:
// 1. The model generates reasoning with LaTeX/curly braces, then opens a span
