//     AppendConstrainedToken preserves parser.IsValidPrefix(currentConstrainedOut).
//   OpenConstrainedSpan: sets currentConstrainedOut := [], valid by precondition.
//   CloseSpanWithinBudget: postcondition guarantees insideOut ==>
//     parser.IsValidPrefix(currentOut).
// progress:
//   Free-text loop: each iteration increments steps by 1 and appends at most
//     one token, so |generated| <= |generatedPrefix| + steps.
//   Constrained loop: CloseSpanIfComplete costs 1 step; SafeRepetitionPenaltyStep
//     + AppendConstrainedToken costs 1 step and appends at most one token.
//   OpenConstrainedSpan: costs 1 step, appends "<<".
//   CloseSpanWithinBudget with budget = remainBudget: by postcondition
//     |generatedOut| <= |generated| + remainBudget; we set steps := maxSteps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Think step by step. Write your reasoning in plain text. At the very end, output exactly one answer like: The answer is <<EXPR>> where EXPR uses only variable names, numbers, +, -, *, /, //, %, (, ) — no LaTeX, no {curly braces}, no backslashes, no ** operator.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
// Reserve ~40% of budget for constrained span; use 60% for free reasoning
