// Phase 5: Force a final answer span if we have budget and no complete span yet
if !insideConstrainedOut && steps < maxSteps {
  var openCount := CSDHelpers.CountTokenOccurrences(generated, "<<");
  var closeCount := CSDHelpers.CountTokenOccurrences(generated, ">>");
  if openCount == 0 || openCount > closeCount {
