    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases (maxSteps - steps) + (innerLimit4 - innerSteps4)
  {
    if innerSteps4 >= minInnerSteps {
      var cg4b, ci4b, cc4b, closed4b := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      if closed4b {
        generated := cg4b;
        insideConstrainedOut := ci4b;
        currentConstrainedOut := cc4b;
        steps := steps + 1;
        hasCompletedSpan := true;
      } else {
        var cp4 := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next4 := helpers.ConstrainedStep(lm, parser, cp4, currentConstrainedOut, eosToken);
        steps := steps + 1;
        innerSteps4 := innerSteps4 + 1;
        if next4 == eosToken {
          break;
        } else {
          var ag4, ai4, ac4 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next4);
          generated := ag4;
          insideConstrainedOut := ai4;
          currentConstrainedOut := ac4;
        }
      }
    } else {
      var cp4m := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next4m := helpers.ConstrainedStep(lm, parser, cp4m, currentConstrainedOut, eosToken);
      steps := steps + 1;
      innerSteps4 := innerSteps4 + 1;
      if next4m == eosToken {
        break;
      } else {
        var ag4m, ai4m, ac4m := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next4m);
        generated := ag4m;
        insideConstrainedOut := ai4m;
        currentConstrainedOut := ac4m;
      }
    }
  }

  // Close if still open
  if insideConstrainedOut && steps < maxSteps {
    var spanBudget4: nat := 40;
    var remaining4 := maxSteps - steps;
    if spanBudget4 > remaining4 {
      spanBudget4 := remaining4;
    }
    if spanBudget4 > 0 {
      var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget4);
      generated := wg4;
      insideConstrainedOut := wi4;
      currentConstrainedOut := wc4;
      steps := steps + spanBudget4;
      if !insideConstrainedOut {
        hasCompletedSpan := true;
      }
    }
  }
}

// Phase 5: If no span completed at all, force open one
if !insideConstrainedOut && !hasCompletedSpan && steps + 2 <= maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
  steps := steps + 1;

  var innerSteps5: nat := 0;
  var innerLimit5: nat := 60;

  while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps5 < innerLimit5
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases (maxSteps - steps) + (innerLimit5 - innerSteps5)
  {
    if innerSteps5 >= minInnerSteps {
      var cg5, ci5, cc5, closed5 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      if closed5 {
        generated := cg5;
        insideConstrainedOut := ci5;
        currentConstrainedOut := cc5;
        steps := steps + 1;
        hasCompletedSpan := true;
      } else {
        var cp5 := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next5 := helpers.ConstrainedStep(lm, parser, cp5, currentConstrainedOut, eosToken);
        steps := steps + 1;
        innerSteps5 := innerSteps5 + 1;
        if next5 == eosToken {
          break;
        } else {
          var ag5, ai5, ac5 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5);
          generated := ag5;
          insideConstrainedOut := ai5;
          currentConstrainedOut := ac5;
        }
      }
    } else {
      var cp5m := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next5m := helpers.ConstrainedStep(lm, parser, cp5m, currentConstrainedOut, eosToken);
      steps := steps + 1;
      innerSteps5 := innerSteps5 + 1;
      if next5m == eosToken {
        break;
      } else {
        var ag5m, ai5m, ac5m := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5m);
        generated := ag5m;
        insideConstrainedOut := ai5m;
        currentConstrainedOut := ac5m;
      }
    }
  }

  if insideConstrainedOut && steps < maxSteps {
    var remainBudget5: nat := maxSteps - steps;
    if remainBudget5 > 40 {
      remainBudget5 := 40;
    }
    if remainBudget5 > 0 {
      var wg5, wi5, wc5 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainBudget5);
      generated := wg5;
      insideConstrainedOut := wi5;
      currentConstrainedOut := wc5;
      steps := steps + remainBudget5;
    }
  }
}

// Phase 6: Final safety close
if insideConstrainedOut && steps < maxSteps {
  var finalBudget := maxSteps - steps;
  if finalBudget > 0 {
    var wgf, wif, wcf := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, finalBudget);
    generated := wgf;
    insideConstrainedOut := wif;
    currentConstrainedOut := wcf;
    steps := steps + finalBudget;
  }
}

cost := steps;
